import{_ as r,r as a,o as c,c as i,e as s,a as e,s as n}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"List Columns - October CMS - 3.x","titleTemplate":false,"description":"Learn how to define columns in a list structure.","frontmatter":{"subtitle":"Learn how to define columns in a list structure."},"headers":[{"level":2,"title":"Available Columns","slug":"available-columns","link":"#available-columns","children":[]},{"level":2,"title":"Column Properties","slug":"column-properties","link":"#column-properties","children":[{"level":3,"title":"Custom Value Selection","slug":"custom-value-selection","link":"#custom-value-selection","children":[]},{"level":3,"title":"Nested Column Selection","slug":"nested-column-selection","link":"#nested-column-selection","children":[]},{"level":3,"title":"Direct SQL Selection","slug":"direct-sql-selection","link":"#direct-sql-selection","children":[]},{"level":3,"title":"Related Column Selection","slug":"related-column-selection","link":"#related-column-selection","children":[]},{"level":3,"title":"Tooltip","slug":"tooltip","link":"#tooltip","children":[]}]}],"relativePath":"3.x/element/list-columns.md","filePath":"3.x/element/list-columns.md"}'),p={name:"3.x/element/list-columns.md"};function u(d,t,m,h,g,k){const o=a("pre-heading"),l=a("post-heading");return c(),i("div",null,[s(o),t[0]||(t[0]=e("h1",null,"List Columns",-1)),s(l),t[1]||(t[1]=n(`<p>List Columns are column definitions used by lists. These are referred to by the following areas.</p><ul><li><a href="./../extend/lists/list-controller.html">Backend List Controller</a></li><li><a href="./../extend/forms/relation-controller.html">Backend Relation Controller</a></li></ul><p>All list columns are identified as their individual <strong>type</strong> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">mycolumn</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> number
        <span class="token comment"># ...</span>
</code></pre></div><h2 id="available-columns"><a href="#available-columns" class="header-anchor">#</a> Available Columns</h2><p>The following list columns are available:</p>`,6)),t[2]||(t[2]=e("div",{class:"content-list-p",markdown:"1"},[e("p",null,[e("a",{href:"./lists/column-text.html"},"Text"),e("a",{href:"./lists/column-number.html"},"Number"),e("a",{href:"./lists/column-image.html"},"Image"),e("a",{href:"./lists/column-switch.html"},"Switch"),e("a",{href:"./lists/column-summary.html"},"Summary"),e("a",{href:"./lists/column-datetime.html"},"Date & Time"),e("a",{href:"./lists/column-selectable.html"},"Selectable"),e("a",{href:"./lists/column-linkage.html"},"Linkage"),e("a",{href:"./lists/column-partial.html"},"Partial"),e("a",{href:"./lists/column-colorpicker.html"},"Color Picker"),e("a",{href:"./lists/column-currency.html"},"Currency")])],-1)),t[3]||(t[3]=n(`<h2 id="column-properties"><a href="#column-properties" class="header-anchor">#</a> Column Properties</h2><p>For each column can specify these properties (where applicable):</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the list column to the user.</td></tr><tr><td><strong>type</strong></td><td>defines how this column should be rendered.</td></tr><tr><td><strong>default</strong></td><td>specifies the default value for the column if value is empty.</td></tr><tr><td><strong>searchable</strong></td><td>include this column in the list search results. Default: <code>false</code>.</td></tr><tr><td><strong>invisible</strong></td><td>specifies if this column is hidden by default. Default: <code>false</code>.</td></tr><tr><td><strong>sortable</strong></td><td>specifies if this column can be sorted. Default: <code>true</code>.</td></tr><tr><td><strong>sortableDefault</strong></td><td>specifies if this column is sorted by default. This should only be used on a single sortable column. Supported values: <code>asc</code>, <code>desc</code>.</td></tr><tr><td><strong>clickable</strong></td><td>if set to false, disables the default click behavior when the column is clicked. Default: true.</td></tr><tr><td><strong>select</strong></td><td>defines a custom SQL select statement to use for the value. If a <code>relation</code> is specified, this refers to a column on the related database table.</td></tr><tr><td><strong>valueFrom</strong></td><td>defines a model attribute to use for the source value. If a <code>relation</code> is specified, this refers to the attribute of the relation and eager loads the relation.</td></tr><tr><td><strong>displayFrom</strong></td><td>defines a model attribute to use for the display value.</td></tr><tr><td><strong>relation</strong></td><td>defines a model relationship name as a source, used with <code>select</code> or <code>valueFrom</code>.</td></tr><tr><td><strong>relationCount</strong></td><td>display the number of related records as the column value. Must be used with the <code>relation</code> option. Default: <code>false</code></td></tr><tr><td><strong>relationWith</strong></td><td>eager load the specified relation definition with the list query. Useful to improve performance of nested column selections.</td></tr><tr><td><strong>cssClass</strong></td><td>assigns a CSS class to the column container.</td></tr><tr><td><strong>headCssClass</strong></td><td>assigns a CSS class to the column header container.</td></tr><tr><td><strong>width</strong></td><td>sets the column width, can be specified in percents (10%) or pixels (50px). There could be a single column without width specified, it will be stretched to take the available space.</td></tr><tr><td><strong>align</strong></td><td>specifies the column alignment. Possible values are <code>left</code>, <code>right</code> and <code>center</code>.</td></tr><tr><td><strong>permissions</strong></td><td>the <a href="./../extend/backend/permissions.html">permissions</a> that the current backend user must have in order for the column to be used. Supports either a string for a single permission or an array of permissions of which only one is needed to grant access.</td></tr><tr><td><strong>order</strong></td><td>a numerical weight when determining the display order, default value increments at 100 points per column.</td></tr><tr><td><strong>after</strong></td><td>place this column after another existing column name using the display order (+1).</td></tr><tr><td><strong>before</strong></td><td>place this column before another existing column name using the display order (-1).</td></tr><tr><td><strong>tooltip</strong></td><td>adds an icon with a tooltip after the column label. See below for more detailed settings.</td></tr></tbody></table></div><h3 id="custom-value-selection"><a href="#custom-value-selection" class="header-anchor">#</a> Custom Value Selection</h3><p>It is possible to change the source and display values for each column. If you want to source the column value from another column, do so with the <code>valueFrom</code> option.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">other_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Something Great
    <span class="token key atrule">valueFrom</span><span class="token punctuation">:</span> name
</code></pre></div><p>If you want to keep the source column value but display a different value from the model attribute, use the <code>displayFrom</code> option.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status_code</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Status
    <span class="token key atrule">displayFrom</span><span class="token punctuation">:</span> status_label
</code></pre></div><p>This is mostly applicable when a <a href="./../extend/database/mutators.html">model accessor</a> is used to modify the display value. This is useful where you want to display a certain value, but sort and search by a different value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStatusLabelAttribute</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">title_case</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">status_code</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="nested-column-selection"><a href="#nested-column-selection" class="header-anchor">#</a> Nested Column Selection</h3><p>In some cases it makes sense to retrieve a column value from a nested data structure, such as a <a href="./../extend/database/relations.html">model relationship</a> column or a <a href="./../extend/system/models.html">jsonable array</a>. The following example would look for the value in PHP equivalent of <code>$record-&gt;content-&gt;title</code> or <code>$record-&gt;content[&#39;title&#39;]</code> respectively.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code>content<span class="token punctuation">[</span>title<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Title
    <span class="token key atrule">sortable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>The only drawback of doing this is the column cannot use searchable or sortable options. To make the column searchable, and for performance reasons, we recommend duplicating its value on the local database table using <a href="./../extend/database/model.html">model events</a>. Alternatively, you can use the <code>relation</code> property described further below.</p><h3 id="direct-sql-selection"><a href="#direct-sql-selection" class="header-anchor">#</a> Direct SQL Selection</h3><p>The <code>select</code> property allows you to create a column using a custom select statement. Any valid SQL SELECT statement works here.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">full_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
    <span class="token key atrule">select</span><span class="token punctuation">:</span> concat(first_name<span class="token punctuation">,</span> <span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> last_name)
</code></pre></div><h3 id="related-column-selection"><a href="#related-column-selection" class="header-anchor">#</a> Related Column Selection</h3><p>The <code>relation</code> property allows you to display related columns as part of the database query, allowing for searching and sorting of that column. The <code>relation</code> is set to the name of the <a href="./../database/relations.html">model relationship</a>. In the next example the <strong>name</strong> value will be translated to the name attribute found in the related model (eg: <code>$model-&gt;name</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">group_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Group
    <span class="token key atrule">relation</span><span class="token punctuation">:</span> groups
    <span class="token key atrule">select</span><span class="token punctuation">:</span> name
</code></pre></div><p>To display a column that shows the number of related records, use the <code>relationCount</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">users_count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Users
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">relation</span><span class="token punctuation">:</span> users
    <span class="token key atrule">relationCount</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><div class="custom-block warning"><p>Be careful not to name relations the same as existing database columns. For example, using a name <code>group_id</code> could break the group relation due to a naming conflict.</p></div><h3 id="tooltip"><a href="#tooltip" class="header-anchor">#</a> Tooltip</h3><p>The <code>tooltip</code> property enhances list columns by adding an informational icon in the column header. Hovering over this icon displays a tooltip, offering additional context or details about the column. This feature aids in providing users with guidance or clarification for understanding column content.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Count
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">tooltip</span><span class="token punctuation">:</span> Number of users in the group
</code></pre></div><p>In addition to providing a tooltip <code>title</code>, you can also specify the <code>icon</code> (<a href="./../element/available-icons.html">available icons</a>) and the <code>placement</code> (<code>right</code>, <code>bottom</code>, <code>left</code>, default value is <code>top</code>) of the tooltip.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Count
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">tooltip</span><span class="token punctuation">:</span>
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Number of users in the group
        <span class="token key atrule">placement</span><span class="token punctuation">:</span> bottom
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>users
</code></pre></div>`,28))])}const b=r(p,[["render",u]]);export{y as __pageData,b as default};
